export const FISHING_RIVAL_NAMES=["Alice Giffard", "Old Walter FitzHugh", "Agnes FitzRobert", "Robert de Vesci", "Matilda de Montfort"];
export function migrateCharacterNames(state){
 const rename=new Map(AUTHORED_CHARACTER_RENAMES.map(c=>[c.old,c.new]));
 const contest=state.sideAdventures?.fishing?.contest;
 for(const rival of contest?.rivals||[])if(rename.has(rival.name))rival.name=rename.get(rival.name);
 // Existing wild battles store trainer presentation text inside their checkpoint.
 return state;
}
export function migrateBattleCharacterNames(battle){
 if(!battle?.trainer?.id)return battle;
 const row=AUTHORED_CHARACTER_RENAMES.find(c=>c.character_id===battle.trainer.id);
 if(row)battle.trainer.name=row.new;
 return battle;
}
